def receive_data(rx_data):
    # 读取串口回复数据
    rcv_data = ser.read(len(rx_data))
    rcv_data = [byte for byte in rcv_data]
    #print(' '.join([format(num, "02x") for num in rcv_data]))
    time.sleep(0.1)
    if rx_data == rcv_data:
        return 1
    else:
        return 0

def send_uart_data(tx_data, rx_data):
    ser.reset_input_buffer()
    ser.write(tx_data)
    # 等待数据发送完成
    ser.flush()
    #print(' '.join([format(num, "02x") for num in tx_data]))
    timeout_count = 0
    while not receive_data(rx_data):
        time.sleep(0.1)
        timeout_count = timeout_count + 1
        if timeout_count > 20:
            print("接收超时!!!")
            ser.close()
            print("关闭串口")
            break

def convert_to_hex_array(file_path):
    with open(file_path, 'rb') as f:
        # 读取二进制文件内容
        binary_data = f.read()
    # 将二进制数据转换为十六进制字符串
    hex_data = ''.join(format(byte, '02X') for byte in binary_data)
    # 将十六进制字符串转换为十六进制数组
    hex_array = bytearray.fromhex(hex_data)
    return hex_array
def set_slice_to_zero(arr, start_index, end_index):
    if 0 <= start_index <= end_index < len(arr):
        arr[start_index:end_index + 1] = [0] * (end_index - start_index + 1)

def hex_to_byte_array(hex_string):
    byte_array = hex_string.to_bytes(4, 'big')
    return byte_array

