    crc = crc32(crc_param)
    # 1 将crc写进cmd
    crc_value = hex_to_byte_array(crc)
    uart_cmd[2] = crc_value[3]
    uart_cmd[3] = crc_value[2]
    uart_cmd[4] = crc_value[1]
    uart_cmd[5] = crc_value[0]
    uart_cmd = uart_cmd[:256]
    send_uart_data(uart_cmd, uart_evt)

    print("开始下载 patch")

    residual_size = app_size
    const_app_size_temp = 0
    patch_4k_count = 0
    process_bar_counter = 0
    #每次只能写入4k，重复操作
    while residual_size > 0:
        set_slice_to_zero(patch_data, 0, 4*1024-1)
        if residual_size > 4*1024:
            app_size_temp = 4*1024
            const_app_size_temp = app_size_temp
            patch_data = binfile_2_hex[patch_4k_count*4*1024:((patch_4k_count+1)*4*1024)]
            residual_size = residual_size - 4 * 1024
        else:
            app_size_temp = residual_size
            const_app_size_temp = app_size_temp
            patch_data[:const_app_size_temp] = binfile_2_hex[patch_4k_count*4*1024:(patch_4k_count*4*1024+const_app_size_temp)]
            residual_size = 0

        # 发送packet header包
        set_slice_to_zero(uart_cmd, 1, 255)
        set_slice_to_zero(uart_evt, 1, 255)
        uart_cmd[1] = 0x03
        #固件偏移位置
        app_offset = patch_4k_count * 4*1024
        offset_value = hex_to_byte_array(app_offset)
        uart_cmd[2] = offset_value[3]
        uart_cmd[3] = offset_value[2]
        uart_cmd[4] = offset_value[1]
        uart_cmd[5] = offset_value[0]
        #固件大小
        size_value = hex_to_byte_array(const_app_size_temp)
        uart_cmd[6] = size_value[3]
        uart_cmd[7] = size_value[2]
        uart_cmd[8] = size_value[1]
        uart_cmd[9] = size_value[0]
        #固件crc
        byte_arr = bytes(patch_data[:const_app_size_temp])
        app_crc = crc32(byte_arr)
        app_crc_value = hex_to_byte_array(app_crc)
        uart_cmd[10] = app_crc_value[3]
        uart_cmd[11] = app_crc_value[2]
        uart_cmd[12] = app_crc_value[1]
        uart_cmd[13] = app_crc_value[0]
        #设置evt
        uart_evt[1] = 0x03
        send_uart_data(uart_cmd, uart_evt)

        #发送固件
        set_slice_to_zero(uart_cmd, 1, 255)
        set_slice_to_zero(uart_evt, 1, 255)
        uart_cmd[1] = 0x04
        uart_evt[1] = 0x04
        patch_count = 256 - 3
        app_size_count = app_size
        patch_4k_count = patch_4k_count + 1
        while app_size_temp > 0:
            #判断剩余固件大小
            if app_size_temp < patch_count:
                patch_count = app_size_temp
            uart_cmd[2] = patch_count
            for i in range(patch_count):
                process_bar(process_bar_counter, app_size)#下载进度条
                process_bar_counter += 1
                uart_cmd[i + 3] = patch_data[i + (const_app_size_temp - app_size_temp)]
            send_uart_data(uart_cmd, uart_evt)
            set_slice_to_zero(uart_cmd, 2, 255)
            set_slice_to_zero(uart_evt, 2, 255)
            app_size_temp = app_size_temp - patch_count

    sys.stdout.flush()
    # 校验固件
    uart_cmd = uart_cmd[:256]
    set_slice_to_zero(uart_cmd, 1, 255)
    set_slice_to_zero(uart_evt, 1, 255)
    uart_cmd[1] = 0x05
    uart_evt[1] = 0x05
    send_uart_data(uart_cmd, uart_evt)

    # 复位重启
    uart_cmd = uart_cmd[:256]
    set_slice_to_zero(uart_cmd, 1, 10)
    set_slice_to_zero(uart_evt, 1, 10)
    uart_cmd[1] = 0x06
    uart_evt[1] = 0x06
    send_uart_data(uart_cmd, uart_evt)

    ser.close()
    print("\n下载完成！")
